/**
 * @distilled.cloud/e2b -- E2B SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from E2B's API descriptions, mirrored at
 * `specs/spec-mirror-e2b/specs/`. Everything else in this folder is
 * hand-written.
 *
 * Control-plane modules (`sandboxes`, `templates`, `volumes`, `secrets`,
 * `snapshots`, `webhooks`, …) authenticate with the team API key. The envd
 * modules (`envd`, `process`, `filesystem`) address one running sandbox,
 * streaming calls included — provide `sandboxConnection`.
 * `volumeContent` authenticates with one volume's token — provide
 * `volumeConnection`.
 *
 * @example
 * ```ts
 * import * as E2B from "@distilled.cloud/e2b";
 *
 * const sandbox = yield* E2B.sandboxes.createSandbox({ templateID: "base" });
 * ```
 */
export * from "./credentials.ts";
export * from "./connections.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  E2BProtocol,
  EnvdProtocol,
  VolumeContentProtocol,
  type E2BOpError,
  type E2BOpContext,
  type EnvdOpContext,
  type VolumeContentOpContext,
} from "./protocol.ts";
export { paginateToken } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
